def is_transaction_description_suspicious(description: str, api_key: str = None) -> bool:
    """
    Ask OpenAI GPT-4o whether a transaction description looks suspicious.

    Returns True when the model indicates suspicion, otherwise False.
    """
    if not description or not description.strip():
        return False

    api_key = api_key or os.getenv("OPENAI_API_KEY")
    if not api_key:
        logger.warning("OPENAI_API_KEY is not set; skipping OpenAI fraud check")
        return False

    payload = {
        "model": "gpt-4o",
        "messages": [
            {
                "role": "system",
                "content": "You are a fraud detection assistant. Reply only with 'yes' or 'no'.",
            },
            {
                "role": "user",
                "content": (
                    "Does this transaction description seem suspicious or potentially fraudulent? "
                    f"Description: {description}"
                ),
            },
        ],
        "temperature": 0,
        "max_tokens": 1,
    }

    req = request.Request(
        "https://api.openai.com/v1/chat/completions",
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
        },
        method="POST",
    )

    try:
        with request.urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read().decode("utf-8"))
            content = data["choices"][0]["message"]["content"].strip().lower()
            return content.startswith("y")
    except error.HTTPError as e:
        logger.error(f"OpenAI fraud check failed: {e.code} {e.reason}")
    except Exception as e:
        logger.error(f"OpenAI fraud check failed: {str(e)}")

    return False


